            await cdp.send(
                "DOM.setFileInputFiles",
                {"files": [remote_file_path], "nodeId": input_node["nodeId"]},
            )

            await asyncio.sleep(20)

    except Exception as e:
        print(f"Error: {e}")
    finally:
        await hb_client.sessions.stop(session.id)

if __name__ == "__main__":
    asyncio.run(main())
